// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: pink; icon-glyph: moon;

/* Berry Blast widget for Scriptable · anandamide.ks
   Shows Mr Idli Billu Bhayankar Sanyal or Ms Chutney Sanyal with your cycle day and next period.

   Widget parameter (touch and hold the widget > Edit Widget > Parameter):
     billu      always Billu
     chutney    always Chutney
     (empty)    they take turns each day
     discreet   add this to hide cycle details, e.g. "chutney discreet"

   Run the script once inside Scriptable to sign in. Run it again any time to preview or sign out. */

const SITE = "https://anandamide-ks.github.io/berry-blast/";
const DAY = 864e5;
const IMG = {
  billu: "",
  billuSleep: "",
  chutney: "",
  chutneySleep: ""
};

const C = {
  paper: Color.dynamic(new Color("#F4F1F7"), new Color("#1A121F")),
  card: Color.dynamic(new Color("#FFFFFF"), new Color("#241A2B")),
  ink: Color.dynamic(new Color("#2B1A36"), new Color("#F1EAF5")),
  muted: Color.dynamic(new Color("#6E6078"), new Color("#A99BB3")),
  period: Color.dynamic(new Color("#C4284F"), new Color("#EC5C7E")),
  fertile: Color.dynamic(new Color("#1E8C83"), new Color("#4CC2B7")),
  ovu: Color.dynamic(new Color("#C98612"), new Color("#EDB44A")),
};
const NAMES = { billu: "Mr Idli Billu", chutney: "Ms Chutney" };
const LINES = {
  "Period": ["Hot water bottle season. Go gently.", "Permission granted to cancel plans.", "Tea, blanket, and absolutely no heroics."],
  "Follicular phase": ["Energy on the way up. Good days for big plans.", "Fresh page, fresh cycle.", "The clouds are parting."],
  "Fertile window": ["In full bloom, by the calendar's guess.", "Peak season on the dial."],
  "Estimated ovulation": ["Top of the hill today, give or take.", "The dial says full bloom."],
  "Luteal phase": ["Winding down. Snacks are a valid strategy.", "Slow lane for a while, and that's fine.", "Cosy mode: on."],
  "Period due": ["Any day now. Keep supplies handy.", "The moon is knocking."],
  "late": ["Fashionably late.", "Bodies don't read calendars."],
};
const QUIPS = {
  billu: ["Mrrp.", "Bhayankar by name, soft by nature.", "Chin scratches improve prediction accuracy.", "Feed me first. Then science.", "I sat on the calendar. You're welcome."],
  chutney: ["Hello, I'm Ms Chutney Sanyal.", "Billu talks about you all the time.", "I'm the brains of this operation.", "Spicy by name, sweet by nature.", "Have you had water today?"],
};
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/* ---------- dates ---------- */
function today() { const d = new Date(); return Math.round(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / DAY); }
function num(k) { const p = k.split("-"); return Math.round(Date.UTC(+p[0], +p[1] - 1, +p[2]) / DAY); }
function fmt(n) { const d = new Date(n * DAY); return d.getUTCDate() + " " + MONTHS[d.getUTCMonth()]; }
function fmtRange(a, b) {
  const da = new Date(a * DAY), db = new Date(b * DAY);
  return da.getUTCMonth() === db.getUTCMonth() ? da.getUTCDate() + "–" + fmt(b) : fmt(a) + " – " + fmt(b);
}

/* ---------- storage ---------- */
const fm = FileManager.local();
const dir = fm.joinPath(fm.documentsDirectory(), "berry-blast");
if (!fm.fileExists(dir)) fm.createDirectory(dir, true);
function readJSON(name) { const p = fm.joinPath(dir, name); try { return fm.fileExists(p) ? JSON.parse(fm.readString(p)) : null; } catch (e) { return null; } }
function writeJSON(name, o) { fm.writeString(fm.joinPath(dir, name), JSON.stringify(o)); }
const KC = "berry-blast-session";
function getSession() { try { return Keychain.contains(KC) ? JSON.parse(Keychain.get(KC)) : null; } catch (e) { return null; } }
function setSession(s) { Keychain.set(KC, JSON.stringify(s)); }
function signOut() { if (Keychain.contains(KC)) Keychain.remove(KC); const p = fm.joinPath(dir, "state.json"); if (fm.fileExists(p)) fm.remove(p); }

/* ---------- Berry Blast account ---------- */
async function getConfig() {
  try {
    const r = new Request(SITE + "config.js");
    r.timeoutInterval = 15;
    const t = await r.loadString();
    const u = t.match(/supabaseUrl:\s*"([^"]+)"/), k = t.match(/supabaseKey:\s*"([^"]+)"/);
    if (u && k) { const c = { url: u[1].replace(/\/+$/, ""), key: k[1] }; writeJSON("config.json", c); return c; }
  } catch (e) {}
  return readJSON("config.json");
}
async function token(cfg, grant, body) {
  const r = new Request(cfg.url + "/auth/v1/token?grant_type=" + grant);
  r.method = "POST";
  r.timeoutInterval = 15;
  r.headers = { "apikey": cfg.key, "Content-Type": "application/json" };
  r.body = JSON.stringify(body);
  const j = await r.loadJSON();
  if (!j || !j.access_token) {
    const m = (j && (j.error_description || j.msg || j.message || j.error)) || "Sign-in failed";
    const e = new Error(/invalid login credentials/i.test(m) ? "Wrong email or password." : m);
    e.auth = true;
    throw e;
  }
  const s = { access: j.access_token, refresh: j.refresh_token, exp: Date.now() + ((j.expires_in || 3600) - 120) * 1000, uid: j.user && j.user.id, email: j.user && j.user.email };
  setSession(s);
  return s;
}
async function signInInteractive(cfg) {
  const a = new Alert();
  a.title = "Sign in to Berry Blast";
  a.message = "Use the same email and password as in the app. The widget only reads your private widget summary.";
  a.addTextField("Email", "");
  a.addSecureTextField("Password", "");
  a.addAction("Sign in");
  a.addCancelAction("Cancel");
  const i = await a.presentAlert();
  if (i === -1) return null;
  return token(cfg, "password", { email: a.textFieldValue(0).trim(), password: a.textFieldValue(1) });
}
async function fetchState(cfg, s) {
  if (Date.now() > s.exp) s = await token(cfg, "refresh_token", { refresh_token: s.refresh });
  const r = new Request(cfg.url + "/rest/v1/widget_state?select=summary,updated_at&owner_id=eq." + encodeURIComponent(s.uid));
  r.timeoutInterval = 15;
  r.headers = { "apikey": cfg.key, "Authorization": "Bearer " + s.access };
  const j = await r.loadJSON();
  if (!Array.isArray(j)) throw new Error((j && j.message) || "Couldn't read your cycle.");
  return j[0] || null;
}

/* ---------- cycle maths (same as the app) ---------- */
function compute(sm) {
  const T = today(), ls = num(sm.lastStart), le = num(sm.lastEnd), avg = sm.avg, pavg = sm.pavg;
  const next = ls + avg, ov = next - 14, cd = T - ls + 1;
  const phase = T <= le ? "Period" : T >= next ? "Period due" : T === ov ? "Estimated ovulation"
    : (T >= ov - 5 && T <= ov + 1) ? "Fertile window" : T < ov - 5 ? "Follicular phase" : "Luteal phase";
  const ovShown = ov >= T ? ov : ov + avg;
  const diff = next - T;
  const nextText = diff > 1 ? "Period in " + diff + " days" : diff === 1 ? "Period tomorrow" : diff === 0 ? "Period due today" : (-diff) + (diff === -1 ? " day late" : " days late");
  return { T, cd, phase, next, diff, late: diff < 0 && phase !== "Period", nextText, ovShown, avg, pavg, stale: cd > 90 };
}
function phaseColor(p) { return p === "Period" || p === "Period due" ? C.period : p === "Fertile window" || p === "Estimated ovulation" ? C.fertile : C.muted; }
function lineFor(M) { const a = LINES[M.late ? "late" : M.phase] || []; return a.length ? a[M.T % a.length] : ""; }

/* ---------- drawing helpers ---------- */
function img(who, sleepy) { return Image.fromData(Data.fromBase64String(IMG[who + (sleepy ? "Sleep" : "")])); }
function text(stack, s, font, color, opts) {
  const t = stack.addText(s);
  t.font = font;
  t.textColor = color;
  t.lineLimit = (opts && opts.lines) || 1;
  t.minimumScaleFactor = (opts && opts.scale) || 0.7;
  return t;
}
const F = {
  big: (n) => new Font("Georgia-Bold", n),
  hand: (n) => new Font("Noteworthy-Bold", n),
  bold: (n) => Font.boldSystemFont(n),
  semi: (n) => Font.semiboldSystemFont(n),
  reg: (n) => Font.systemFont(n),
};
function bubble(stack, s, who, size) {
  const b = stack.addStack();
  b.layoutVertically();
  b.backgroundColor = C.card;
  b.cornerRadius = 12;
  b.setPadding(6, 9, 6, 9);
  text(b, s, F.hand(size || 13), C.period, { lines: 2, scale: 0.75 });
  text(b, NAMES[who].toUpperCase(), F.semi(8), C.muted);
}
function ring(M, size) {
  const ctx = new DrawContext();
  ctx.size = new Size(size, size);
  ctx.opaque = false;
  ctx.respectScreenScale = true;
  const cx = size / 2, r = size / 2 - 7, w = 8;
  const arc = (from, to, color) => {
    const p = new Path(), steps = Math.max(2, Math.ceil((to - from) * 80));
    for (let i = 0; i <= steps; i++) {
      const a = (from + (to - from) * i / steps) * 2 * Math.PI - Math.PI / 2;
      const pt = new Point(cx + r * Math.cos(a), cx + r * Math.sin(a));
      if (i === 0) p.move(pt); else p.addLine(pt);
    }
    ctx.addPath(p); ctx.setStrokeColor(color); ctx.setLineWidth(w); ctx.strokePath();
  };
  arc(0, 1, new Color("#FFFFFF", 0.25));
  if (M && !M.stale) arc(0, Math.min(1, M.cd / M.avg), Color.white());
  ctx.setTextAlignedCenter();
  ctx.setTextColor(Color.white());
  ctx.setFont(Font.boldSystemFont(size * 0.34));
  ctx.drawTextInRect(M && !M.stale ? String(M.cd) : "–", new Rect(0, size * 0.22, size, size * 0.42));
  ctx.setFont(Font.semiboldSystemFont(size * 0.13));
  ctx.drawTextInRect("DAY", new Rect(0, size * 0.62, size, size * 0.2));
  return ctx.getImage();
}

/* ---------- widget layouts ---------- */
function build(family, who, M, msg, discreet) {
  const w = new ListWidget();
  w.url = SITE + "#today";
  w.refreshAfterDate = new Date(Date.now() + 60 * 60 * 1000);
  const sleepy = !!(M && M.phase === "Period" && !discreet);
  const quip = QUIPS[who][today() % QUIPS[who].length];

  if (family === "accessoryCircular") {
    w.addAccessoryWidgetBackground = true;
    if (discreet || !M) { const s = SFSymbol.named("moon.stars.fill"); const i = w.addImage(s.image); i.imageSize = new Size(30, 30); i.tintColor = Color.white(); }
    else { const i = w.addImage(ring(M, 120)); i.imageSize = new Size(58, 58); }
    return w;
  }
  if (family === "accessoryRectangular") {
    if (discreet || !M) { text(w, "Berry Blast", F.bold(14), Color.white()); text(w, msg || quip, F.reg(12), Color.white(), { lines: 2 }); return w; }
    text(w, M.stale ? "No recent period" : "Day " + M.cd + " · " + M.phase, F.bold(14), Color.white());
    text(w, M.nextText + " · " + fmt(M.next), F.reg(12), Color.white());
    text(w, "Fertile " + fmtRange(M.ovShown - 5, M.ovShown + 1), F.reg(12), Color.white());
    return w;
  }
  if (family === "accessoryInline") {
    text(w, discreet || !M ? "Berry Blast" : (M.stale ? "Berry Blast · log your period" : "Day " + M.cd + " · " + M.nextText.toLowerCase()), F.reg(12), Color.white());
    return w;
  }

  w.backgroundColor = C.paper;
  const big = family === "large" || family === "extraLarge";
  w.setPadding(14, 14, 14, 14);

  if (family === "small") {
    const top = w.addStack();
    top.layoutHorizontally();
    top.topAlignContent();
    const ci = top.addImage(img(who, sleepy)); ci.imageSize = new Size(78, 75);
    top.addSpacer();
    w.addSpacer();
    if (msg) { text(w, msg, F.semi(12), C.ink, { lines: 3, scale: 0.8 }); return w; }
    if (discreet) { text(w, quip, F.hand(14), C.period, { lines: 3 }); return w; }
    text(w, M.stale ? "Log a period" : "Day " + M.cd, F.big(28), C.ink);
    text(w, M.stale ? "to refresh predictions" : M.phase, F.semi(12), phaseColor(M.phase));
    text(w, M.nextText, F.reg(11), C.muted);
    return w;
  }

  // medium, large
  const row = w.addStack();
  row.layoutHorizontally();
  row.centerAlignContent();
  const left = row.addStack();
  left.layoutVertically();
  left.centerAlignContent();
  const ci = left.addImage(img(who, sleepy)); ci.imageSize = big ? new Size(120, 116) : new Size(104, 100);
  row.addSpacer(12);
  const right = row.addStack();
  right.layoutVertically();
  if (msg) {
    text(right, "Berry Blast", F.big(20), C.ink);
    right.addSpacer(4);
    text(right, msg, F.reg(12), C.muted, { lines: 4, scale: 0.8 });
  } else if (discreet) {
    text(right, "Berry Blast", F.big(20), C.ink);
    right.addSpacer(6);
    bubble(right, quip, who, 14);
  } else {
    text(right, "CYCLE DAY", F.semi(9), C.muted);
    text(right, M.stale ? "–" : String(M.cd), F.big(big ? 40 : 32), C.ink);
    text(right, M.stale ? "No recent period" : M.phase, F.semi(12), phaseColor(M.phase));
    right.addSpacer(6);
    bubble(right, M.stale ? "Log your latest period and I'll recalculate." : lineFor(M), who, 13);
  }
  row.addSpacer();
  if (!msg && !discreet) {
    w.addSpacer(big ? 14 : 8);
    if (big) {
      const facts = [["Next period", fmt(M.next) + " (" + M.nextText.toLowerCase() + ")", C.period], ["Fertile window", fmtRange(M.ovShown - 5, M.ovShown + 1), C.fertile], ["Estimated ovulation", fmt(M.ovShown), C.ovu], ["Typical cycle", M.avg + " days", C.muted], ["Typical period", M.pavg + " days", C.muted]];
      for (const [k, v, col] of facts) {
        const fr = w.addStack(); fr.layoutHorizontally(); fr.centerAlignContent();
        const dot = fr.addStack(); dot.size = new Size(6, 6); dot.cornerRadius = 3; dot.backgroundColor = col;
        fr.addSpacer(8); text(fr, k, F.reg(13), C.muted); fr.addSpacer(); text(fr, v, F.semi(13), C.ink);
        w.addSpacer(7);
      }
      w.addSpacer();
      text(w, "supervised by Mr Idli Billu & Ms Chutney", F.hand(11), C.muted);
    } else {
      const fr = w.addStack(); fr.layoutHorizontally();
      text(fr, M.nextText + " · " + fmt(M.next), F.semi(11), C.ink);
      fr.addSpacer();
      text(fr, "Fertile " + fmtRange(M.ovShown - 5, M.ovShown + 1), F.reg(11), C.muted);
    }
  }
  return w;
}

/* ---------- main ---------- */
async function main() {
  const param = String(args.widgetParameter || "").toLowerCase();
  const discreet = /discreet|private|hide/.test(param);
  const who = /chutney/.test(param) ? "chutney" : /billu|idli/.test(param) ? "billu" : (today() % 2 ? "chutney" : "billu");
  let M = null, msg = null;
  const cfg = await getConfig();
  if (!cfg) msg = "Couldn't reach Berry Blast. Check your internet connection.";
  else {
    let s = getSession();
    if (!s && !config.runsInWidget) {
      try { s = await signInInteractive(cfg); } catch (e) { msg = e.message; }
    }
    if (!s && !msg) msg = "Open Scriptable and run Berry Blast once to sign in.";
    if (s) {
      let row = null;
      try {
        row = await fetchState(cfg, s);
        if (row) writeJSON("state.json", row);
        else msg = "Turn on “Keep the widget up to date” in Berry Blast → Settings → iPhone widget.";
      } catch (e) {
        if (e.auth) { signOut(); msg = "Signed out. Open Scriptable and run Berry Blast to sign in again."; }
        else { row = readJSON("state.json"); if (!row) msg = "Couldn't load your cycle. Check your internet connection."; }
      }
      if (row && row.summary) {
        if (row.summary.none || !row.summary.lastStart) msg = "Log a period in Berry Blast and I'll start counting.";
        else M = compute(row.summary);
      }
    }
  }
  return { who, M, msg, discreet };
}

const R = await main();
if (config.runsInWidget) {
  Script.setWidget(build(config.widgetFamily, R.who, R.M, R.msg, R.discreet));
} else {
  const m = new Alert();
  m.title = "Berry Blast widget";
  m.message = R.msg ? R.msg : (getSession() ? "Signed in as " + (getSession().email || "you") + ". The widget is ready to add to your home screen." : "");
  m.addAction("Preview small");
  m.addAction("Preview medium");
  m.addAction("Preview large");
  if (getSession()) m.addDestructiveAction("Sign out");
  m.addCancelAction("Done");
  const i = await m.presentSheet();
  if (i === 0) await build("small", R.who, R.M, R.msg, R.discreet).presentSmall();
  else if (i === 1) await build("medium", R.who, R.M, R.msg, R.discreet).presentMedium();
  else if (i === 2) await build("large", R.who, R.M, R.msg, R.discreet).presentLarge();
  else if (i === 3 && getSession()) { signOut(); const a = new Alert(); a.title = "Signed out"; a.message = "Run Berry Blast again to sign in."; a.addAction("OK"); await a.presentAlert(); }
}
Script.complete();
